UPDATE places SET slug='old-eagle-pub', name='Old Eagle Pub', category='FOOD', latitude=51.5427573, longitude=-0.1394201, status='published', description_en='The Old Eagle is a Camden neighbourhood pub near the Regent’s Canal, known for a relaxed garden, live entertainment and an interior assembled from mismatched decorative details. It is more local pub than destination restaurant.', description_it='The Old Eagle è un pub di quartiere a Camden vicino al Regent’s Canal, noto per il giardino informale, l’intrattenimento dal vivo e gli interni composti da dettagli decorativi diversi. È soprattutto un pub locale, non un ristorante di destinazione.', editorial_hook_en='The Old Eagle is a Camden neighbourhood pub near the Regent’s Canal, known for a relaxed garden, live entertainment and an interior assembled from mismatched decorative details. It is more local pub than destination restaurant.', editorial_hook_it='The Old Eagle è un pub di quartiere a Camden vicino al Regent’s Canal, noto per il giardino informale, l’intrattenimento dal vivo e gli interni composti da dettagli decorativi diversi. È soprattutto un pub locale, non un ristorante di destinazione.', official_url='', google_maps_url='https://www.google.com/maps?q=51.5427573,-0.1394201', price_text='Check venue', access_type='VARIABLE', access_notes_en='Pub hours, food service and bookings can change; check the venue before travelling.', access_notes_it='Orari del pub, servizio cucina e prenotazioni possono cambiare: controlla il locale prima di partire.', opening_hours_json='{}', tourist_intensity=40, crowd_scope='VENUE', visit_minutes=75, best_time='EVENING', weather_fit='RAIN_FRIENDLY', visit_mode='STOP', mood_quiet=1, mood_unexpected=2, mood_beautiful=1, mood_weird=0, mood_local=3, mood_green=0, mood_atmospheric=3, mood_lively=3, mood_reviewed=1, mood_confidence='MEDIUM', mood_basis='USER_CURATED_SOURCE+PLACE_SPECIFIC_EDITORIAL_REVIEW+FOOD_CATEGORY', source_type='user-csv', source_ref='London Tour 2023- Food